import { type TeamHuntState } from "@hunt/public-client";
import React from "react";
import { hydrateRoot } from "react-dom/client";
import { ErrataDataProvider } from "../../../client/ErrataProvider";
import GameworldZoneClient from "../../../components/overworld/GameworldZoneClient";
import { loadAviariaScenes } from "../gameworld/scene-loaders/aviaria";
import AviariaBody from "./AviariaBody";
import { type AviariaState } from "./types";

const AviariaManager = ({
  initialState,
  initialTeamState,
}: {
  initialState: AviariaState;
  initialTeamState: TeamHuntState;
}) => {
  return (
    <ErrataDataProvider initialTeamState={initialTeamState}>
      <GameworldZoneClient
        roundSlug="aviaria"
        initialState={initialState}
        initialTeamState={initialTeamState}
        sceneLoader={loadAviariaScenes}
        render={({ state, teamState, gameNode }) => {
          return (
            <AviariaBody
              state={state}
              teamState={teamState}
              gameNode={gameNode}
            />
          );
        }}
      />
    </ErrataDataProvider>
  );
};

const elem = document.getElementById("aviaria-root");
if (elem) {
  const { initialAviariaState: state, initialTeamState } =
    window as unknown as {
      initialAviariaState: AviariaState;
      initialTeamState: TeamHuntState;
    };
  hydrateRoot(
    elem,
    <AviariaManager initialState={state} initialTeamState={initialTeamState} />,
  );
} else {
  console.error(
    "Could not mount AviariaManager because #aviaria-root was nowhere to be found",
  );
}
