import * as Phaser from "phaser";
import type { TiledRegiObject } from "../../common/tiled/types";
import type { CustomObject } from "../../common/types";

export class RegiDoor extends Phaser.GameObjects.Zone implements CustomObject {
  public readonly regiId: "DOT" | "DASH" | "ENTRY" | "EXIT";

  constructor(scene: Phaser.Scene, config: TiledRegiObject) {
    // Center the zone in the regi door area
    const centerX = config.x + config.width / 2;
    const centerY = config.y + config.height / 2;

    super(scene, centerX, centerY, config.width, config.height);

    this.regiId = config.id;

    // Add to scene
    scene.add.existing(this);

    // Enable physics on this zone
    scene.physics.world.enable(this);

    // Initially enabled (regi doors are always active)
    this.enableObject();
  }

  public enableObject(): void {
    (this.body as Phaser.Physics.Arcade.Body).enable = true;
    this.active = true;
  }

  public disableObject(): void {
    (this.body as Phaser.Physics.Arcade.Body).enable = false;
    this.active = false;
  }
}
