import * as Phaser from "phaser";
import { ASSET_KEYS, LANTERN_FRAME_KEYS } from "../../common/assets";
import { type CustomObject } from "../../common/types";

enum MorseSymbol {
  PAUSE = "PAUSE",
  DOT = "DOT",
  DASH = "DASH",
}

const DOT_DURATION = 200;
const DASH_DURATION = 800;
const LETTER_DELAY = 2000;
const MESSAGE_END_DELAY = 5000;

type MorseCodeLanternConfig = {
  x: number;
  y: number;
  message: string;
};

export class MorseCodeLantern
  extends Phaser.Physics.Arcade.Sprite
  implements CustomObject
{
  private message: string;
  private currentIndex = 0;
  private morseSequence: { symbol: MorseSymbol; duration: number }[] = [];
  private startTimer: Phaser.Time.TimerEvent | null = null;
  private isPlaying = false;
  private currentStepStartTime = 0;

  constructor(scene: Phaser.Scene, config: MorseCodeLanternConfig) {
    super(
      scene,
      config.x,
      config.y,
      ASSET_KEYS.LANTERN,
      LANTERN_FRAME_KEYS.LANTERN_OFF,
    );

    this.message = config.message;

    scene.add.existing(this);
    scene.physics.add.existing(this);
    this.setOrigin(0, 1).setImmovable(true).setDepth(2);

    this.generateMorseSequence();

    this.disableObject();
  }

  public update(): void {
    const visible = this.scene.cameras.main.worldView.contains(this.x, this.y);
    if (!this.isPlaying && visible) {
      if (this.startTimer === null) {
        // Wait 2 seconds after the lantern becomes visible. If it's still visible then start playback.
        this.startTimer = this.scene.time.delayedCall(2000, () => {
          this.startTimer = null;
          const visible = this.scene.cameras.main.worldView.contains(
            this.x,
            this.y,
          );
          if (visible) {
            this.startMorseCodePlayback();
          }
        });
      }
    } else if (this.isPlaying && !visible) {
      this.stopMorseCodePlayback();
    }

    if (this.isPlaying) {
      this.updatePlayback();
    }
  }

  private generateMorseSequence(): void {
    this.morseSequence = [];

    for (const symbol of this.message) {
      if (symbol === ".") {
        this.morseSequence.push({
          symbol: MorseSymbol.DOT,
          duration: DOT_DURATION,
        });
        this.morseSequence.push({
          symbol: MorseSymbol.PAUSE,
          duration: DOT_DURATION,
        });
      } else if (symbol === "-") {
        this.morseSequence.push({
          symbol: MorseSymbol.DASH,
          duration: DASH_DURATION,
        });
        this.morseSequence.push({
          symbol: MorseSymbol.PAUSE,
          duration: DOT_DURATION,
        });
      } else if (symbol === " ") {
        this.morseSequence.push({
          symbol: MorseSymbol.PAUSE,
          duration: LETTER_DELAY,
        });
      } else {
        throw new Error("invalid symbol");
      }
    }

    // Add message end delay for repetition
    this.morseSequence.push({
      symbol: MorseSymbol.PAUSE,
      duration: MESSAGE_END_DELAY,
    });
  }

  public startMorseCodePlayback(): void {
    if (this.isPlaying || this.morseSequence.length === 0) {
      return;
    }

    this.isPlaying = true;
    this.currentIndex = 0;
    this.currentStepStartTime = this.scene.time.now;
    this.startCurrentStep();
  }

  public stopMorseCodePlayback(): void {
    this.isPlaying = false;
    if (this.startTimer) {
      this.startTimer.destroy();
      this.startTimer = null;
    }
    this.setFrame(LANTERN_FRAME_KEYS.LANTERN_OFF);
  }

  private updatePlayback(): void {
    if (!this.isPlaying || this.morseSequence.length === 0) {
      return;
    }

    const currentStep = this.morseSequence[this.currentIndex];
    const elapsed = this.scene.time.now - this.currentStepStartTime;

    if (elapsed >= currentStep.duration) {
      // Move to next step
      this.currentIndex++;
      if (this.currentIndex >= this.morseSequence.length) {
        this.currentIndex = 0; // Loop back to start
      }

      this.currentStepStartTime = this.scene.time.now;
      this.startCurrentStep();
    }
  }

  private startCurrentStep(): void {
    const step = this.morseSequence[this.currentIndex];

    if (step.symbol === MorseSymbol.DOT || step.symbol === MorseSymbol.DASH) {
      this.setFrame(LANTERN_FRAME_KEYS.LANTERN_ON);
    } else {
      this.setFrame(LANTERN_FRAME_KEYS.LANTERN_OFF);
    }
  }

  public disableObject(): void {
    this.stopMorseCodePlayback();
    (this.body as Phaser.Physics.Arcade.Body).enable = false;
    this.active = false;
    this.visible = false;
  }

  public enableObject(): void {
    (this.body as Phaser.Physics.Arcade.Body).enable = true;
    this.active = true;
    this.visible = true;
    this.setFrame(LANTERN_FRAME_KEYS.LANTERN_OFF);
    this.startMorseCodePlayback();
  }

  public destroy(): void {
    this.stopMorseCodePlayback();
    super.destroy();
  }
}
