import { AviariaGameScene } from "../scenes/aviaria-game-scene";
import { AviariaPreloadScene } from "../scenes/aviaria-preload-scene";
import { GameOverScene } from "../scenes/game-over-scene";
import { SCENE_KEYS } from "../scenes/scene-keys";
import { UIScene } from "../scenes/ui-scene";
import type { SceneLoader } from "./types";

export const loadAviariaScenes: SceneLoader = (game) => {
  game.scene.add(SCENE_KEYS.AVIARIA_PRELOAD_SCENE, AviariaPreloadScene, false);
  game.scene.add(SCENE_KEYS.AVIARIA_GAME_SCENE, AviariaGameScene, false);
  game.scene.add(SCENE_KEYS.UI_SCENE, UIScene, false);
  game.scene.add(SCENE_KEYS.GAME_OVER_SCENE, GameOverScene, false);
  game.scene.start(SCENE_KEYS.AVIARIA_PRELOAD_SCENE);
};
