import MOUNTAIN_EVENTS from "../assets/data/levels/mountain/events.json";
import MOUNTAIN_LEVEL from "../assets/data/levels/mountain/mountain.json";
import MOUNTAIN_BACKGROUND from "../assets/data/levels/mountain/mountain_background.png";
import MOUNTAIN_FOREGROUND from "../assets/data/levels/mountain/mountain_foreground.png";
import MOUNTAIN_NPCS from "../assets/data/levels/mountain/npcs.json";
import MOUNTAIN_READABLES from "../assets/data/levels/mountain/readables.json";
import SNOWFLAKE_IMG from "../assets/images/effects/snowflake.png";
import BIRD_SONG_JSON from "../assets/images/npcs/mountain/bird_song.json";
import BIRD_SONG_IMG from "../assets/images/npcs/mountain/bird_song.png";
import CARDINAL_JSON from "../assets/images/npcs/mountain/cardinal.json";
import CARDINAL_IMG from "../assets/images/npcs/mountain/cardinal.png";
import GRACKLE_BLACK_JSON from "../assets/images/npcs/mountain/grackle_black.json";
import GRACKLE_BLACK_IMG from "../assets/images/npcs/mountain/grackle_black.png";
import GRACKLE_BLUE_JSON from "../assets/images/npcs/mountain/grackle_blue.json";
import GRACKLE_BLUE_IMG from "../assets/images/npcs/mountain/grackle_blue.png";
import GRACKLE_GREEN_JSON from "../assets/images/npcs/mountain/grackle_green.json";
import GRACKLE_GREEN_IMG from "../assets/images/npcs/mountain/grackle_green.png";
import GRACKLE_PINK_JSON from "../assets/images/npcs/mountain/grackle_pink.json";
import GRACKLE_PINK_IMG from "../assets/images/npcs/mountain/grackle_pink.png";
import GRACKLE_RED_JSON from "../assets/images/npcs/mountain/grackle_red.json";
import GRACKLE_RED_IMG from "../assets/images/npcs/mountain/grackle_red.png";
import GRACKLE_YELLOW_JSON from "../assets/images/npcs/mountain/grackle_yellow.json";
import GRACKLE_YELLOW_IMG from "../assets/images/npcs/mountain/grackle_yellow.png";
import HAWK_JSON from "../assets/images/npcs/mountain/hawk.json";
import HAWK_IMG from "../assets/images/npcs/mountain/hawk.png";
import HELIBIRD_JSON from "../assets/images/npcs/mountain/helibird.json";
import HELIBIRD_IMG from "../assets/images/npcs/mountain/helibird.png";
import OLD_MAN_JSON from "../assets/images/npcs/mountain/old_man.json";
import OLD_MAN_IMG from "../assets/images/npcs/mountain/old_man.png";
import YELLOWBIRD_JSON from "../assets/images/npcs/mountain/yellowbird.json";
import YELLOWBIRD_IMG from "../assets/images/npcs/mountain/yellowbird.png";
import DOORS_JSON from "../assets/images/world_objects/doors.json";
import DOORS_IMG from "../assets/images/world_objects/doors.png";
import LANTERN_JSON from "../assets/images/world_objects/lantern.json";
import LANTERN_IMG from "../assets/images/world_objects/lantern.png";
import CHIRP_SOUND from "../assets/sounds/chirp.mp3";
import { ASSET_KEYS } from "../common/assets";
import { BasePreloadScene } from "./base-preload-scene";
import { SCENE_KEYS } from "./scene-keys";

export class AviariaPreloadScene extends BasePreloadScene {
  constructor() {
    super(SCENE_KEYS.AVIARIA_PRELOAD_SCENE);
  }

  public preload(): void {
    super.preload();
    this.#loadAviariaAssets();
  }

  public create(): void {
    super.create();
    this.#createAviariaAnimations();
  }

  #loadAviariaAssets(): void {
    // Load mountain level
    this.load.image(ASSET_KEYS.MOUNTAIN_BACKGROUND, MOUNTAIN_BACKGROUND);
    this.load.image(ASSET_KEYS.MOUNTAIN_FOREGROUND, MOUNTAIN_FOREGROUND);
    this.load.tilemapTiledJSON(ASSET_KEYS.MOUNTAIN_LEVEL, MOUNTAIN_LEVEL);

    // Load flying bird NPCs
    this.load.aseprite(
      ASSET_KEYS.GRACKLE_BLACK,
      GRACKLE_BLACK_IMG,
      GRACKLE_BLACK_JSON,
    );
    this.load.aseprite(
      ASSET_KEYS.GRACKLE_BLUE,
      GRACKLE_BLUE_IMG,
      GRACKLE_BLUE_JSON,
    );
    this.load.aseprite(
      ASSET_KEYS.GRACKLE_GREEN,
      GRACKLE_GREEN_IMG,
      GRACKLE_GREEN_JSON,
    );
    this.load.aseprite(
      ASSET_KEYS.GRACKLE_PINK,
      GRACKLE_PINK_IMG,
      GRACKLE_PINK_JSON,
    );
    this.load.aseprite(
      ASSET_KEYS.GRACKLE_RED,
      GRACKLE_RED_IMG,
      GRACKLE_RED_JSON,
    );
    this.load.aseprite(
      ASSET_KEYS.GRACKLE_YELLOW,
      GRACKLE_YELLOW_IMG,
      GRACKLE_YELLOW_JSON,
    );
    // Load NPCs
    this.load.aseprite(ASSET_KEYS.OLD_MAN, OLD_MAN_IMG, OLD_MAN_JSON);
    this.load.aseprite(ASSET_KEYS.BIRD_SONG, BIRD_SONG_IMG, BIRD_SONG_JSON);
    this.load.aseprite(ASSET_KEYS.CARDINAL, CARDINAL_IMG, CARDINAL_JSON);
    this.load.aseprite(ASSET_KEYS.HAWK, HAWK_IMG, HAWK_JSON);
    this.load.aseprite(ASSET_KEYS.HELIBIRD, HELIBIRD_IMG, HELIBIRD_JSON);
    this.load.aseprite(ASSET_KEYS.YELLOWBIRD, YELLOWBIRD_IMG, YELLOWBIRD_JSON);

    // Load zone-specific data
    this.load.json(ASSET_KEYS.EVENTS, MOUNTAIN_EVENTS);
    this.load.json(ASSET_KEYS.NPCS, MOUNTAIN_NPCS);
    this.load.json(ASSET_KEYS.READABLE_MESSAGES, MOUNTAIN_READABLES);

    this.load.aseprite(ASSET_KEYS.LANTERN, LANTERN_IMG, LANTERN_JSON);
    this.load.image(ASSET_KEYS.SNOWFLAKE, SNOWFLAKE_IMG);

    this.load.aseprite(ASSET_KEYS.DOORS, DOORS_IMG, DOORS_JSON);

    // Load sounds
    this.load.audio(ASSET_KEYS.CHIRP_SFX, CHIRP_SOUND);
  }

  #createAviariaAnimations(): void {
    this.anims.createFromAseprite(ASSET_KEYS.GRACKLE_BLACK);
    this.anims.createFromAseprite(ASSET_KEYS.GRACKLE_BLUE);
    this.anims.createFromAseprite(ASSET_KEYS.GRACKLE_GREEN);
    this.anims.createFromAseprite(ASSET_KEYS.GRACKLE_PINK);
    this.anims.createFromAseprite(ASSET_KEYS.GRACKLE_RED);
    this.anims.createFromAseprite(ASSET_KEYS.GRACKLE_YELLOW);
    this.anims.createFromAseprite(ASSET_KEYS.OLD_MAN);
    this.anims.createFromAseprite(ASSET_KEYS.BIRD_SONG);
    this.anims.createFromAseprite(ASSET_KEYS.CARDINAL);
    this.anims.createFromAseprite(ASSET_KEYS.HAWK);
    this.anims.createFromAseprite(ASSET_KEYS.HELIBIRD);
    this.anims.createFromAseprite(ASSET_KEYS.YELLOWBIRD);
    this.anims.createFromAseprite(ASSET_KEYS.LANTERN);
  }
}
